def dns_query(name, server, port=53):
    def qname(n): return b''.join(bytes([len(l)])+l.encode() for l in n.split('.'))+b'\0'
    pkt = struct.pack('>HHHHHH', 0x1234, 0x0100, 1,0,0,0) + qname(name) + struct.pack('>HH',1,1)
